#include <stdio.h>

int main(void) {
    int x[6];
    for (int i = 0; i < 6; i++) {
        scanf("%d", &x[i]);
    }

    for (int top = 0; top < 6; top++) {
        for (int i = 0; i < 6; i++) {
            if (i == top) continue;
            for (int j = i + 1; j < 6; j++) {
                if (j == top) continue;
                if (x[i] + x[j] != x[top]) continue;

                int remaining = 0;
                for (int k = 0; k < 6; k++) {
                    if (k != top && k != i && k != j) {
                        remaining += x[k];
                    }
                }

                if (remaining == x[top]) {
                    printf("S\n");
                    return 0;
                }
            }
        }
    }

    printf("N\n");
    return 0;
}
